HERE = Path(__file__).parent
out = HERE/'public'
out.mkdir(exist_ok=True)
registry = json.loads((HERE/'research.json').read_text())
S = registry['sources']

def link(key):
    keys = key if isinstance(key,(list,tuple)) else (key,)
    return ' · '.join(f'<a href="{escape(S[k]["url"], quote=True)}">{escape(S[k]["title"])} ↗</a>' for k in keys)


def table(caption, head, rows, kind='verified'):
    return ('<div class="table-wrap"><table data-kind="'+kind+'"><caption>'+caption+
            '</caption><thead><tr>'+''.join('<th scope="col">'+escape(x)+'</th>' for x in head)+
            '</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row[:-1])+
            '<td>'+link(row[-1])+'</td></tr>' for row in rows)+'</tbody></table></div>')


nav=[('index.html','Overview'),('decision.html','Decision'),('projection.html','Projections'),('stress.html','Black swan'),('process.html','Process'),('law.html','Tax & law'),('costs.html','Costs'),('questions.html','Open questions'),('suggestions.html','Suggestions'),('suggestions-detail.html','Review details'),('issues.html','Issues to resolve'),('flagged.html','Flagged for review')]

def notice(title, body):
    return '<div class="notice"><b>'+title+'</b><p>'+body+'</p></div>'


def page(fn,title,kicker,description,body):
    links=''.join(f'<a {"aria-current=page" if f==fn else ""} href="{f}">{n}</a>' for f,n in nav)
    (out/fn).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'self'; img-src 'self'; base-uri 'none'; form-action 'none'"><title>{escape(title)} | Inheritance decision guide</title><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><div class="topbar"><a class="logo" href="index.html"><span class="mark">N</span><span>INHERITANCE <small>DECISION GUIDE</small></span></a><span class="topnote">SOURCE CHECKS <i></i> 12–13 NOV 2026</span></div><nav aria-label="Main navigation">{links}</nav></header><main id="main"><div class="heading"><p class="eyebrow">{kicker}</p><h1>{escape(title)}</h1><p class="lead">{description}</p></div>{body}</main><footer><div><b>Inheritance decision guide</b><p>No personal property figures or derived household forecasts are published.</p></div><p>Source checks are dated per item (12–13 November 2026). Illustrations are not forecasts. Rules may change. Not legal, tax, investment or insurance advice.</p><a href="flagged.html">Sources & limitations →</a></footer></body></html>''',encoding='utf-8')


page('index.html','A clearer path forward','EXECUTIVE BRIEF / 01','A future trust inheritance. An already-owned home. Three paths, compared without exposing a household.', '''<section class="hero"><div><span class="pill">WORKING DIRECTION · CONDITIONAL</span><h2>Preserve flexibility.<br>Compare before you commit.</h2><p>Keep the already-owned home as the housing baseline. Evaluate selling the future inherited home and diversifying as the first financial benchmark—not an automatic winner. Renting must justify its after-tax yield and concentrated risk; moving in must justify its housing benefit and costs.</p><a class="button" href="decision.html">See the decision gates <span>↗</span></a></div><div class="hero-side"><span>THE IMPORTANT DISTINCTION</span><h3>Property A<br>Future inheritance.</h3><p>Property B is already owned. Inheriting A does not itself reset B’s assessment or income-tax basis. Keep B’s ongoing rental income in every path unless facts actually change.</p></div></section>'''+table('Executive findings · legal facts and decision judgments are distinguished', ['Topic','Finding','Status','Official context'], [
('Ownership','Model only the incremental change from A; do not count existing B rent as a new inheritance benefit. Owner-supplied baseline note: hold existing occupancy and rental continuity constant for comparison. This anonymized note is unverified and does not establish tenancy, legal-unit status, title or an occupancy fact.','Owner-supplied placeholder; not independently verified',['estate','rent']),
('Property tax','Renting A generally means reassessment absent another exclusion. Living there may qualify for limited family-home relief—not necessarily the old tax bill.','Eligibility unknown','boe'),
('Basis','Date-of-death value generally determines inherited basis; a trust alone does not guarantee a step-up.','General rule; trust review needed','basis'),
('Estate exposure','2026 basic exclusion $15,000,000; published 2027 exclusion $15,480,000. These are not per-beneficiary allowances.','Official current amounts','irs27'),
('Insurance','No official property-specific owner or landlord premium established. A generic average is not a quote.','Unverified amount: blank','insurance'),
('Recommendation','Use sell-and-diversify as the benchmark when housing is already available and net rental yield is low; reassess with verified costs and risk preferences.','Conditional judgment; no proven personal winner','sec')
])+'''<div class="cards"><article><span class="num">01</span><h3>Official facts</h3><p>Current tax rules with direct links and important exceptions.</p><a href="law.html">Tax & law →</a></article><article><span class="num">02</span><h3>Transparent examples</h3><p>Standalone fictional numbers, rounded to $10. Never substituted for private inputs.</p><a href="projection.html">Annual illustrations →</a></article><article><span class="num">03</span><h3>Uneven conditions</h3><p>Historical context plus clearly invented stress paths. No false probabilities.</p><a href="stress.html">Black swan →</a></article></div>'''+'''<h2>Executive summary</h2>'''+table('What this guide concludes now, and what would change it',['Element','Statement','Basis','Official context'],[
('Decision to be made','At the future transfer, the inherited home can be lived in, rented, or sold and the proceeds reinvested. All three are compared after tax on the same end date.','Recommended structure, not a finding about the household','rent'),
('Baseline','The home already owned is treated as fixed: its housing use and its existing rental income do not change merely because another home is inherited. Only the incremental effect of the inherited home enters the comparison.','Analytical rule; the alternative would double-count existing income','estate'),
('Strongest general presumption','When housing is already available and net rental yield is low, selling and diversifying is the benchmark the other paths must beat, because it removes concentration, illiquidity and landlord risk.','Conditional judgment, not a personal recommendation','sec'),
('What usually defeats that presumption','A low inherited assessment that survives the transfer, high transaction and tax costs of selling, strong and sustained local appreciation, or a genuine intention to occupy the home.','Mechanisms identified from the rules; magnitudes not verified for the household','boe'),
('Largest single legal lever','Property-tax treatment at transfer. If the family-home conditions are met the old assessed value can continue; if the home is rented instead, the usual result is reassessment at market value.','Rule is fixed by statute; eligibility is unverified','boepub'),
('Largest single financial unknown','Whether the estate is inside or outside the federal exclusion, and what the exclusion will be at a transfer two to three decades away.','Exclusion amounts are published only for 2026 and 2027','irs27'),
('What cannot be concluded','No household-specific winner, no projected value, no binding premium and no tax liability. The facts that would decide it are private and unverified.','Deliberate: a filled-in number would be invented','basis'),
('What happens next','Six gates in order, and a checklist of open items each with an owner and an evidence source. Nothing is decided by this site.','Review workflow, not advice','boe')
])+notice('Privacy first — rounding is not anonymization','This public guide withholds assessment histories, locations tied to the household, rents, unit counts and owner-derived forecasts. Officially unverified personal amounts remain blank. Synthetic examples are teaching aids, not filled-in missing values. Older Git history may still expose prior data; noindex is not access control.'))

rows=[
('1 · Establish baseline','Keep B’s current income and housing use unchanged across the comparison unless a documented change is intended.','Do not invent a new tenancy, rent for a vacated space, title status or legal-unit status.','rent'),
('2 · Verify basis and estate liquidity','Determine whether A receives an income-tax basis adjustment and how estate obligations are allocated.','A large estate may need liquidity before distributions; a trust does not eliminate estate tax.','estate'),
('3 · Price the sell benchmark','Net proceeds = sale price − debt − selling costs − gain tax − allocated settlement obligations.','Do not tax gross sale proceeds as capital gain or assume every sale is tax free.','basis'),
('4 · Test rent','After-tax cash = collected rent − operating expenses − capital cash outlay − debt service − actual income tax.','Depreciation is not a cash expense. Capital work is not automatically deductible as repairs.','rent'),
('5 · Test live-in','Compare incremental occupancy costs, genuine housing value and any qualifying tax savings.','Do not assume B’s existing rents stop, or that vacant space becomes legally rentable. A principal-residence claim must be genuine.','boe'),
('6 · Choose under uncertainty','Compare after-tax liquidation wealth on the same end date, plus liquidity and loss tolerance.','If outcomes are close, avoid treating a tiny modeled advantage as certainty.','sec')]
first=ledger()['first_year']
comparison=[]
for horizon in (10,20,30):
    for growth in (.01,.03,.05):
        result=ledger(house_growth=growth,years=horizon)
        comparison.append((str(horizon),f'{growth:.0%}',money(result['sell_wealth']),money(result['rent_wealth']),money(result['sell_wealth']-result['rent_wealth']),'rent'))
page('decision.html','Compare the paths','DECISION FRAMEWORK / 02','Maximize after-tax results without confusing known rules, unknown inputs and assumed returns.',table('Decision gates · proposed workflow, not legal determinations',['Gate','Analysis','Guardrail','Official context'],rows)+table('The two properties are not interchangeable · baseline rule applied to every comparison',['Question','Already-owned home (B)','Inherited home (A)','Why it changes the answer','Official context'],[
('Who owns it now','The Inheritor already owns it','The Transferor owns it until the future transfer','Inheritance adds an asset; it does not create a second housing need. Housing is therefore already covered before A arrives.','estate'),
('Is its ownership affected by the inheritance','No; A’s transfer is not a change of ownership for B','Yes; the death is a change of ownership for A for property-tax purposes','Do not apply A’s reassessment, or A’s relief, to B. Its assessment continues on its own track.','rtc'),
('Rental income in the comparison','Existing rents continue in every path unless a documented change occurs','Any rent is a new income only if a lawful tenancy is actually created','Counting B’s current rent as a benefit of inheriting A would double-count income the household already has.','rent'),
('Property-tax treatment at transfer','Unchanged','Reassessment is the default; limited family-home relief is possible only if the conditions and claims are met','This is the main cost difference between living in A and renting it out.','boepub'),
('Housing cost avoided by living in A','The household still bears B’s costs and keeps its use','Living in A replaces, rather than adds to, the housing already owned','A dollar of housing benefit only exists if the move actually replaces other housing cost; that is a private fact.','sec'),
('What a sale of A changes','Nothing for B','Converts one concentrated, illiquid asset into diversified liquid assets after tax','Diversification is the reason selling is the benchmark, not a claim that it always wins.','sec'),
('What a sale of B would change','Out of scope in this guide; selling B is a separate decision with its own tax and rent consequences','Renting A would then become the household’s housing fallback','Recorded as an open item rather than assumed away.','sell')
])+notice('Provisional plan, not a verified optimum','Retain the existing home as the baseline. At inheritance, compare a prompt sale against a documented rental offer and a genuine desire to occupy A. Favor sale/diversification if net rent and realistic appreciation cannot compensate for taxes, repairs, illiquidity and concentration. Favor keeping A only if it clears that hurdle or provides valued housing benefits. No household winner can be honestly established with the missing facts.')+'''<h2>A numerical teaching example</h2><p><b>Invented, unrelated home: $1,000,000 value and inherited basis; no mortgage.</b> Immediate sale cost 5%, giving $950,000 to invest. Effective portfolio return 5% annually <em>after all investment taxes and fees, including liquidation</em> is assumed, not promised. Rent starts at $36,000 per year; vacancy 5%; management 8% of collected rent. First-year property tax $12,000, insurance $3,000, water $2,000, electricity $1,000, repairs $6,000 and capital work $4,000. Rent and non-tax costs rise 2.5%; assessed base rises 2%. These are invented assumptions, NOT official prices or regional estimates.</p>'''+table('Synthetic first-year cash bridge · official links explain tax concepts, not assumed amounts',['Line','Illustrative amount','Treatment','Official context'],[
('Collected rent',money(first['rent']),'Gross rent less assumed vacancy','rent'),
('Total cash expenses',money(first['expenses']),'Includes assumed capital work; excludes income tax and noncash depreciation','rent'),
('Income tax',money(first['income_tax']),'30% of positive illustrative taxable income; no immediate loss benefit','rent'),
('Cash available',money(first['cash']),'Collected rent minus cash expenses minus income tax','rent')
], 'illustration')+'''<p>Building share 40%; simplified depreciation over 27.5 years, capped at building basis. Income tax assumed 30%; terminal gain assumed 30% with a 35% combined effective tax on gain attributable to depreciation (not a federal statutory rate). Capital work adds basis but receives no further depreciation in this deliberately simplified example. Year-end cash is invested at 5%. Terminal sale cost 5%; rent ending wealth includes after-tax sale plus invested cash. Sale losses receive no benefit. Ordinary tax losses receive no carryover. Annual straight-line depreciation omits actual first/last-year conventions. These approximations can change the ranking.</p>'''+table('Synthetic sensitivity · $10-rounded after-tax liquidation wealth; NOT a household recommendation',['Years after transfer','Home growth assumption','Sell & invest','Rent, then sell','Sell minus rent','Official tax context'],comparison,'illustration')+notice('Why live-in has no fabricated ranking','Without an official valuation of alternative housing use or documented private preference, assigning a dollar benefit to moving would be invented. Live-in stays a separate decision gate. This illustrative comparison excludes B, estate-tax allocations, leverage and Section 121 benefits from both paths. No claim that these omissions are immaterial.'))

